-- 038 część 4/61: lokale gastronomiczne w Polsce ze stroną www.
-- Źródło: OpenStreetMap (ODbL), Overpass, 21 października 2026.
-- Wstawia tylko wtedy, gdy w promieniu 40 m nie ma już opublikowanego pinu.
-- Linków Uber Eats, Glovo, Pyszne, Wolt i Bolt Food tu nie ma — OSM ich nie podaje.

insert into public.pins (title, description, cuisine, city, address, website, phone, coords, status, is_official)
select
  v.title,
  'Menu i ceny są na stronie lokalu.',
  nullif(v.cuisine, ''),
  nullif(v.city, ''),
  nullif(v.address, ''),
  v.website,
  nullif(v.phone, ''),
  st_setsrid(st_makepoint(v.lng, v.lat), 4326)::geography,
  'published',
  false
